#include <iostream>
#include <vector>
using namespace std;
using Graph = vector<vector<int>>;

struct Frame {
    int vertex;
    size_t pos;
};

struct Traversal {
    vector<int> par;
    vector<int> entered;
    vector<int> finished;
};

Traversal dfs_forest(const Graph& adj) {
    int n = static_cast<int>(adj.size()) - 1;
    Traversal result{vector<int>(n + 1, 0),
                     vector<int>(n + 1, 0),
                     vector<int>(n + 1, 0)};
    vector<Frame> frames;
    int timer = 0;

    for (int start = 1; start <= n; ++start) {
        if (result.entered[start] != 0) {
            continue;
        }
        result.entered[start] = ++timer;
        frames.push_back({start, 0});
        while (!frames.empty()) {
            int vertex = frames.back().vertex;
            if (frames.back().pos == adj[vertex].size()) {
                result.finished[vertex] = ++timer;
                frames.pop_back();
                continue;
            }
            int next = adj[vertex][frames.back().pos];
            ++frames.back().pos;
            if (result.entered[next] != 0) {
                continue;
            }
            result.par[next] = vertex;
            result.entered[next] = ++timer;
            frames.push_back({next, 0});
        }
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    Graph adj(n + 1);
    for (int edge = 0; edge < m; ++edge) {
        int first, second;
        cin >> first >> second;
        adj[first].push_back(second);
        adj[second].push_back(first);
    }

    Traversal result = dfs_forest(adj);
    for (int vertex = 1; vertex <= n; ++vertex) {
        cout << vertex << ' ' << result.par[vertex] << ' '
             << result.entered[vertex] << ' ' << result.finished[vertex] << '\n';
    }
    return 0;
}

